const body = $input.first().json.body ?? $input.first().json;
const source = String(body.source || '').toLowerCase();
const offset = Math.max(0, parseInt(body.offset ?? 0, 10) || 0);
const limit = Math.min(50, Math.max(1, parseInt(body.limit ?? 20, 10) || 20));

const TAB_MAP = {
  receipt: 'Receipt',
  email: 'Email',
  mileage: 'Milage',
};

const sheetName = TAB_MAP[source];
if (!sheetName) {
  return [{ json: { valid: false, error: 'source must be receipt, email, or mileage' } }];
}

return [{ json: { valid: true, source, offset, limit, sheetName } }];

const req = $('Parse Request').first().json;
const rows = $input.all().map((item) => item.json);

function asString(value) {
  if (value == null) return '';
  return String(value).trim();
}

function asNumber(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function excelOrIsoDate(value) {
  const raw = asString(value);
  if (!raw) return '';
  if (/^\d{4}-\d{2}-\d{2}/.test(raw)) return raw.slice(0, 10);
  const serial = Number(raw);
  if (!Number.isFinite(serial) || serial <= 0) return raw;
  if (serial > 100000) return new Date(serial).toISOString().slice(0, 10);
  const ms = (serial - 25569) * 86400 * 1000;
  return new Date(ms).toISOString().slice(0, 10);
}

function sortKeyFromRow(row, source) {
  if (source === 'receipt') {
    return asString(row['Submitted At'] || row.Date);
  }
  if (source === 'email') {
    return asString(row.emailTimestamp || row.submittedAt || row.internalDate || row.date);
  }
  return asString(row.submittedAt || row.endTime || row.date);
}

function mapReceiptRow(row) {
  const submittedAt = asString(row['Submitted At']);
  const driveLink = asString(row.link || row['Image Link']);
  return {
    id: submittedAt ? `receipt-${submittedAt}` : `receipt-row-${Math.random()}`,
    status: 'success',
    submittedAt: submittedAt || excelOrIsoDate(row.Date),
    sheetSubmittedAt: submittedAt || undefined,
    imageData: '',
    extractedData: {
      vendor: asString(row.Vendor),
      date: excelOrIsoDate(row.Date),
      total: asNumber(row.Total),
      tax: asNumber(row.Tax),
      currency: asString(row.Currency) || 'CAD',
      category: asString(row.Category),
      items: [],
      itemsSummary: asString(row.Items),
      confidence: asNumber(row.Confidence),
      driveLink: driveLink || undefined,
      submittedAt: submittedAt || undefined,
    },
  };
}

function mapEmailRow(row) {
  const emailTimestamp = asString(row.emailTimestamp || row.internalDate);
  const submittedAt = asString(row.submittedAt || row.date);
  return {
    id: emailTimestamp ? `email-${emailTimestamp}` : `email-row-${Math.random()}`,
    status: 'success',
    submittedAt: submittedAt || emailTimestamp,
    emailTimestamp: emailTimestamp || undefined,
    imageData: '',
    extractedData: {
      vendor: asString(row.vendor),
      date: excelOrIsoDate(row.date),
      total: asNumber(row.total),
      tax: asNumber(row.tax),
      currency: asString(row.currency) || 'CAD',
      category: asString(row.category),
      items: [],
      itemsSummary: asString(row.items),
      confidence: asNumber(row.confidence),
      submittedAt: submittedAt || undefined,
      emailTimestamp: emailTimestamp || undefined,
      transactionType: asString(row.transactionType),
      source: asString(row.source),
      gmailMessageId: asString(row.gmailMessageId || row.messageId),
      driveFilename: asString(row.driveFilename),
    },
  };
}

function mapMileageRow(row) {
  const submittedAt = asString(row.submittedAt);
  return {
    id: submittedAt ? `mileage-${submittedAt}` : `mileage-row-${Math.random()}`,
    status: 'success',
    submittedAt: submittedAt || excelOrIsoDate(row.date),
    sheetSubmittedAt: submittedAt || undefined,
    startTime: asString(row.startTime),
    endTime: asString(row.endTime),
    startLocation: asString(row.startLocation) || undefined,
    endLocation: asString(row.endLocation) || undefined,
    distanceKm: asNumber(row.distanceKm),
    businessPurpose: asString(row.businessPurpose),
    trackingMode: asString(row.trackingMode) === 'Manual' ? 'Manual' : 'GPS',
    deduction: asNumber(row.deduction) || undefined,
  };
}

const mappers = {
  receipt: mapReceiptRow,
  email: mapEmailRow,
  mileage: mapMileageRow,
};

const withSort = rows.map((row) => ({ row, key: sortKeyFromRow(row, req.source) }));
withSort.sort((a, b) => b.key.localeCompare(a.key));

const mapped = withSort
  .map(({ row }) => mappers[req.source](row))
  .filter((item) => {
    if (req.source === 'receipt') return Boolean(item.sheetSubmittedAt || item.extractedData?.vendor);
    if (req.source === 'email') return Boolean(item.emailTimestamp || item.extractedData?.vendor);
    return Boolean(item.sheetSubmittedAt || item.businessPurpose);
  });

const total = mapped.length;
const page = mapped.slice(req.offset, req.offset + req.limit);
const nextOffset = req.offset + page.length;
const hasMore = nextOffset < total;

return [{
  json: {
    success: true,
    source: req.source,
    items: page,
    total,
    offset: req.offset,
    limit: req.limit,
    hasMore,
    nextOffset: hasMore ? nextOffset : null,
  },
}];
